bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
const env=process.env;
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,database:env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
try{
 const s=(await pool.query("SELECT current_schema() s,current_setting('search_path') p,current_database() d")).rows[0];
 console.log('DB_TARGET='+JSON.stringify(s));
 const cols=(await pool.query("SELECT table_schema,table_name,column_name FROM information_schema.columns WHERE table_name='videobot_listings' AND column_name IN ('creator_terms_version','creator_terms_url','paid_video_file_size_bytes') ORDER BY table_schema,column_name")).rows;
 console.log('ALL_LISTING_COLUMN_MATCHES='+JSON.stringify(cols));
 const rows=(await pool.query("SELECT table_schema,COUNT(*)::int n FROM information_schema.columns WHERE table_name='videobot_listings' GROUP BY table_schema")).rows;
 console.log('LISTING_TABLE_SCHEMAS='+JSON.stringify(rows));
 for(const file of ['sql/019_creator_terms_version.sql','sql/023_video_legacy_purchaser_entitlement.sql']){
  const s=fs.readFileSync('/opt/videobot/'+file,'utf8');
  console.log('LIVE_MIGRATION='+JSON.stringify({file,present:s.length>20,hasCreatorTerms:s.includes('ADD COLUMN IF NOT EXISTS creator_terms_version')}));
 }
 const receipt=(await pool.query("SELECT sale_mode,status,COUNT(*)::int AS n FROM videobot_post_receipts GROUP BY sale_mode,status ORDER BY sale_mode,status")).rows;
 console.log('SALES_RECEIPT_COUNTS='+JSON.stringify(receipt));
}finally{await pool.end()}
NODE
